import{_ as l,o as e,c as i,aw as t}from"./chunks/framework.DLufY-ao.js";const _=JSON.parse('{"title":"REST API","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/network/network/api/rest.md","filePath":"wiki/dev-commit/network/network/api/rest.md"}'),r={name:"wiki/dev-commit/network/network/api/rest.md"};function o(n,a,h,s,u,d){return e(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="rest-api" tabindex="-1">REST API <a class="header-anchor" href="#rest-api" aria-label="Permalink to &quot;REST API&quot;">​</a></h1><ul><li><strong>REST</strong> (REpresentational State Transfer - «передача состояния представления») - архитектурный стиль взаимодействия компонентов распределённого приложения в сети. Задает общие принципы организации взаимодействия приложения/сайта с сервером посредством протокола HTTP</li><li>Каждый запрос (REST-запрос) клиента к серверу содержит в себе исчерпывающую информацию о желаемом ответе сервера (желаемом представительном состоянии), и сервер не обязан сохранять информацию о состоянии клиента («клиентской сессии»). Сервер не запоминает состояние пользователя между запросами - в каждом запросе передаётся информация, идентифицирующая пользователя (например, token, полученный через OAuth-авторизацию) и все параметры, необходимые для выполнения операции</li><li>Для веб-служб, построенных с учётом REST (то есть не нарушающих накладываемых им ограничений), применяют термин RESTful</li></ul><h2 id="требования-к-архитектуре-rest" tabindex="-1">Требования к архитектуре REST <a class="header-anchor" href="#требования-к-архитектуре-rest" aria-label="Permalink to &quot;Требования к архитектуре REST&quot;">​</a></h2><h3 id="_1-модель-клиент-сервер" tabindex="-1">1. Модель клиент-сервер <a class="header-anchor" href="#_1-модель-клиент-сервер" aria-label="Permalink to &quot;1. Модель клиент-сервер&quot;">​</a></h3><ul><li>Позволяет отдельным частям развиваться независимо друг от друга</li></ul><h3 id="_2-отсутствие-состояния" tabindex="-1">2. Отсутствие состояния <a class="header-anchor" href="#_2-отсутствие-состояния" aria-label="Permalink to &quot;2. Отсутствие состояния&quot;">​</a></h3><ul><li>Протокол взаимодействия между клиентом и сервером требует соблюдения следующего условия: в период между запросами клиента никакая информация о состоянии клиента на сервере не хранится (Stateless Protocol). Все запросы от клиента должны быть составлены так, чтобы сервер получил всю необходимую информацию для выполнения запроса. Состояние сессии при этом сохраняется на стороне клиента. Информация о состоянии сессии может быть передана сервером какому-либо другому сервису (например, в службу базы данных) для поддержания устойчивого состояния, например, на период установления аутентификации. Клиент инициирует отправку запросов, когда он готов (возникает необходимость) перейти в новое состояние. Во время обработки клиентских запросов считается, что клиент находится в переходном состоянии. Каждое отдельное состояние приложения представлено связями, которые могут быть задействованы при следующем обращении клиента</li></ul><h3 id="_3-кэширование-ответов-сервера" tabindex="-1">3. Кэширование ответов сервера <a class="header-anchor" href="#_3-кэширование-ответов-сервера" aria-label="Permalink to &quot;3. Кэширование ответов сервера&quot;">​</a></h3><ul><li>Ответы сервера, в свою очередь, должны иметь явное или неявное обозначение как кэшируемые или некэшируемые с целью предотвращения получения клиентами устаревших или неверных данных в ответ на последующие запросы</li></ul><h3 id="_4-единообразие-интерфеиса" tabindex="-1">4. Единообразие интерфейса <a class="header-anchor" href="#_4-единообразие-интерфеиса" aria-label="Permalink to &quot;4. Единообразие интерфейса&quot;">​</a></h3><ul><li>Унифицированные интерфейсы позволяют каждому из сервисов развиваться независимо</li></ul><h4 id="требования-предъявляемые-к-унифицированным-интерфеисам" tabindex="-1">Требования, предъявляемые к унифицированным интерфейсам: <a class="header-anchor" href="#требования-предъявляемые-к-унифицированным-интерфеисам" aria-label="Permalink to &quot;Требования, предъявляемые к унифицированным интерфейсам:&quot;">​</a></h4><ul><li>Идентификация ресурсов. Все ресурсы идентифицируются в запросах, например, с использованием URI в интернет-системах. Ресурсы концептуально отделены от представлений, которые возвращаются клиентам. Например, сервер может отсылать данные из базы данных в виде HTML, XML или JSON, ни один из которых не является типом хранения внутри сервера</li><li>Манипуляция ресурсами через представление. Если клиент хранит представление ресурса, включая метаданные — он обладает достаточной информацией для модификации или удаления ресурса</li><li>«Самоописываемые» сообщения. Каждое сообщение содержит достаточно информации, чтобы понять, каким образом его обрабатывать</li><li>Гипермедиа как средство изменения состояния приложения (HATEOAS). Клиенты изменяют состояние системы только через действия, которые динамически определены в гипермедиа на сервере (к примеру, гиперссылки в гипертексте). Исключая простые точки входа в приложение, клиент не может предположить, что доступна какая-то операция над каким-то ресурсом, если не получил информацию об этом в предыдущих запросах к серверу.</li></ul><h3 id="_5-слои" tabindex="-1">5. Слои <a class="header-anchor" href="#_5-слои" aria-label="Permalink to &quot;5. Слои&quot;">​</a></h3><ul><li>Клиент обычно не способен точно определить, взаимодействует он напрямую с сервером или же с промежуточным узлом, в связи с иерархической структурой сетей (подразумевая, что такая структура образует слои). Применение промежуточных серверов способно повысить масштабируемость за счёт балансировки нагрузки и распределённого кэширования. Промежуточные узлы также могут подчиняться политике безопасности с целью обеспечения конфиденциальности информации</li></ul><h3 id="_6-код-по-требованию" tabindex="-1">6. Код по требованию <a class="header-anchor" href="#_6-код-по-требованию" aria-label="Permalink to &quot;6. Код по требованию&quot;">​</a></h3><ul><li>(необязательное ограничение)</li><li>REST может позволить расширить функциональность клиента за счёт загрузки кода с сервера в виде апплетов или сценариев</li></ul><h2 id="преимущества" tabindex="-1">Преимущества <a class="header-anchor" href="#преимущества" aria-label="Permalink to &quot;Преимущества&quot;">​</a></h2><ul><li>Надёжность (за счёт отсутствия необходимости сохранять информацию о состоянии клиента, которая может быть утеряна)</li><li>Производительность (за счёт использования кэша)</li><li>Масштабируемость</li><li>Прозрачность системы взаимодействия (особенно необходимая для приложений обслуживания сети)</li><li>Простота интерфейсов</li><li>Портативность компонентов</li><li>Лёгкость внесения изменений</li><li>Способность эволюционировать, приспосабливаясь к новым требованиям (на примере Всемирной паутины)</li></ul>',19)])])}const m=l(r,[["render",o]]);export{_ as __pageData,m as default};
